```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <cmath>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> T;
    int x;
    while (plik >> x) T.push_back(x);
    int n = T.size();
    int K = 3;

    // a) Najdluzszy podciag z |roznica| <= K
    int maxDl = 1, maxStart = 0;
    int curDl = 1, curStart = 0;

    for (int i = 1; i < n; i++) {
        if (abs(T[i] - T[i - 1]) <= K) {
            curDl++;
        } else {
            if (curDl > maxDl) { maxDl = curDl; maxStart = curStart; }
            curDl = 1; curStart = i;
        }
    }
    if (curDl > maxDl) { maxDl = curDl; maxStart = curStart; }

    cout << "a) Najdluzszy podciag z |roznica| <= " << K << ":" << endl;
    cout << "   Dlugosc: " << maxDl << ", pozycja poczatkowa: " << maxStart + 1 << endl;
    cout << "   Elementy:";
    for (int i = maxStart; i < maxStart + maxDl; i++)
        cout << " " << T[i];
    cout << endl;

    // b) Srednia
    double suma = 0;
    for (int i = maxStart; i < maxStart + maxDl; i++)
        suma += T[i];
    double sr = suma / maxDl;
    cout << endl << "b) Srednia: " << fixed << setprecision(2) << sr << endl;

    // c) Najbardziej odlegly od sredniej
    int najdalszy = T[maxStart];
    double maxOdl = abs(T[maxStart] - sr);
    for (int i = maxStart + 1; i < maxStart + maxDl; i++) {
        double odl = abs(T[i] - sr);
        if (odl > maxOdl) {
            maxOdl = odl;
            najdalszy = T[i];
        }
    }
    cout << endl << "c) Najbardziej odlegly od sredniej: " << najdalszy
         << " (odleglosc: " << fixed << setprecision(2) << maxOdl << ")" << endl;
    return 0;
}
```

